import assert from "node:assert/strict";
import test from "node:test";
import { basicCommands } from "../../../../src/commands/basic.js";
import { streamCommands } from "../../../../src/commands/streams.js";
import { FsError } from "../../../../src/contracts/errors.js";
import { createDeviceFileSystem } from "../../../../src/fs/devices/index.js";
import { createMemoryFileSystem } from "../../../../src/fs/memory/index.js";
import { createMountFileSystem } from "../../../../src/fs/mount/index.js";
import type { ShellExtension } from "../../../../src/shell/extensions.js";
import { readExtension } from "../../../../src/shell/extensions/read/index.js";
import { Shell } from "../../../../src/shell/shell.js";
import { authenticateOracle, nativeOptions, runNative } from "../trap/oracle.js";

interface Expected {
  status: number;
  value: string;
  count: number;
  array: string;
  tail: string;
  stderr: string;
}

interface ReadCase {
  name: string;
  args: string;
  before?: string;
  expected: Partial<Expected>;
  pipe?: Partial<Expected>;
}

const readError = "shell: line 1: read: read error: 3: Bad file descriptor\n";
const missingError = "shell: line 1: read: 9: invalid file descriptor: Bad file descriptor\n";
const nameError = "shell: line 1: read: `bad-name': not a valid identifier\n";
const input = "first word\nsecond tail\n";
const cases: readonly ReadCase[] = [
  { name: "ordinary scalar read error preserves assignment", args: "-u3 value", expected: { stderr: readError } },
  { name: "ordinary array read error preserves cells", args: "-u3 -a values", expected: { stderr: readError } },
  { name: "later readable -u replaces open write-only -u", args: "-u3 -u0 value", expected: { status: 0, value: "first word", tail: "second tail" } },
  { name: "later write-only -u selects read-stage failure", args: "-u0 -u3 value", expected: { stderr: readError } },
  { name: "missing earlier -u cannot be replaced", args: "-u9 -u3 value", expected: { stderr: missingError } },
  { name: "missing later -u precedes all assignment", args: "-u3 -u9 value", expected: { stderr: missingError } },
  { name: "zero count assigns empty scalar despite failed access", args: "-u3 -n0 value", expected: { value: "" } },
  { name: "zero exact count clears array despite failed access", args: "-u3 -N0 -a values", expected: { count: 0, array: "" } },
  { name: "zero count validates scalar target", args: "-u3 -n0 bad-name", expected: { stderr: nameError } },
  { name: "zero exact count validates array target", args: "-u3 -N0 -a bad-name", expected: { stderr: nameError } },
  { name: "zero count diagnoses readonly scalar", before: "readonly fixed;", args: "-u3 -n0 fixed", expected: { stderr: "shell: line 1: fixed: readonly variable\n" } },
  { name: "zero exact count diagnoses readonly array", before: "readonly -a values;", args: "-u3 -N0 -a values", expected: { stderr: "shell: line 1: values: readonly variable\n" } },
  { name: "readiness does not assign scalar", args: "-t0 -u3 value", expected: { status: 0 }, pipe: { status: 1 } },
  { name: "readiness bypasses invalid scalar", args: "-t0 -u3 bad-name", expected: { status: 0 }, pipe: { status: 1 } },
  { name: "readiness bypasses readonly scalar", before: "readonly fixed;", args: "-t0 -u3 fixed", expected: { status: 0 }, pipe: { status: 1 } },
  { name: "readiness preserves array", args: "-t0 -u3 -a values", expected: { status: 0 }, pipe: { status: 1 } },
  { name: "readiness bypasses invalid array", args: "-t0 -u3 -a bad-name", expected: { status: 0 }, pipe: { status: 1 } },
  { name: "readiness precedes zero count", args: "-t0 -u3 -n0 value", expected: { status: 0 }, pipe: { status: 1 } },
  { name: "readiness after zero exact count still wins", args: "-N0 -u3 -t0 -a values", expected: { status: 0 }, pipe: { status: 1 } },
  { name: "positive timeout then scalar assignment", args: "-t.02 -u3 value", expected: { stderr: readError }, pipe: { status: 142, value: "", stderr: "" } },
  { name: "positive TMOUT then array clearing", before: "TMOUT=.02;", args: "-u3 -a values", expected: { stderr: readError }, pipe: { status: 142, count: 0, array: "", stderr: "" } },
  { name: "positive timeout then readonly scalar validation", before: "readonly fixed;", args: "-t.02 -u3 fixed", expected: { stderr: readError }, pipe: { stderr: "shell: line 1: fixed: readonly variable\n" } },
  { name: "positive timeout then invalid array validation", args: "-t.02 -u3 -a bad-name", expected: { stderr: readError }, pipe: { stderr: nameError } },
];

function setup(extensions: readonly ShellExtension[] = [readExtension()]) {
  const fs = createMountFileSystem({ root: createMemoryFileSystem(), mounts: { "/dev": createDeviceFileSystem() } });
  const shell = new Shell({ fs, extensions, limits: { maxWallClockMs: 2000, maxInputBytes: 4096, maxOutputBytes: 65536, maxCommands: 64 } });
  for (const command of [...basicCommands(), ...streamCommands()]) shell.register(command);
  return { shell, fs };
}

function body(entry: ReadCase): string {
  return `value=OLD; fixed=LOCK; values=(KEEP STAY); ${entry.before ?? ""} read -r ${entry.args}; result=$?; printf 'read=%s value=<%s> fixed=<%s> count=%s array=<%s>;' "$result" "$value" "$fixed" "\${#values[@]}" "\${values[*]}"; IFS= read -r tail; printf 'next=%s:<%s>' "$?" "$tail"`;
}

function pipe(bodySource: string): string {
  return `{ { ${bodySource}; } 3>&1 1>&4 | cat; } 4>&1`;
}

function native(script: string, pipeSource = false) {
  const env = { ...process.env };
  assert.equal(env.SAFE_BASH_TEST_BASH_SHA256, "f5b331844c67482075aea7883153127668cc67f83a60a7b4362cc8469a9dc77d");
  const executable = authenticateOracle(env);
  const source = pipeSource
    ? `cat() { local chunk; while IFS= read -r chunk; do printf '%s\\n' "$chunk"; done; }; ${pipe(`[[ -p /dev/fd/3 ]] || exit 97; ${script}`)}`
    : script;
  try {
    return { ...runNative(source, input, env), source };
  } finally { assert.equal(authenticateOracle(env), executable); }
}

function expected(patch: Partial<Expected>) {
  const value: Expected = { status: 1, value: "OLD", count: 2, array: "KEEP STAY", tail: "first word", stderr: "", ...patch };
  return {
    stdout: Buffer.from(`read=${value.status} value=<${value.value}> fixed=<LOCK> count=${value.count} array=<${value.array}>;next=0:<${value.tail}>`),
    stderr: Buffer.from(value.stderr),
  };
}

for (const profile of ["null", "pipe"] as const) for (const entry of cases) {
  test(`descriptor order native/${profile}: ${entry.name}`, nativeOptions(), async context => {
    const source = profile === "pipe" ? pipe(body(entry)) : `{ ${body(entry)}; } 3>/dev/null`;
    const oracle = native(profile === "pipe" ? body(entry) : source, profile === "pipe");
    const capture = expected({ ...entry.expected, ...(profile === "pipe" ? entry.pipe : {}) });
    assert.equal(oracle.status, 0);
    assert.deepEqual(oracle.stdout, capture.stdout);
    assert.deepEqual(oracle.stderr, capture.stderr);
    const subject = setup();
    context.after(() => subject.shell.dispose());
    assert.equal((await subject.fs.stat("/dev/null")).type, "character");
    const actual = await subject.shell.exec(source, { stdin: Buffer.from(input), env: { LC_ALL: "C" } });
    context.diagnostic(JSON.stringify({ source, nativeSource: oracle.source,
      native: { status: oracle.status, stdoutHex: oracle.stdout.toString("hex"), stderrHex: oracle.stderr.toString("hex") },
      actual: { status: actual.exitCode, stdoutHex: Buffer.from(actual.stdoutBytes).toString("hex"), stderrHex: Buffer.from(actual.stderrBytes).toString("hex") },
    }));
    assert.equal(actual.exitCode, oracle.status);
    assert.deepEqual(Buffer.from(actual.stdoutBytes), oracle.stdout);
    assert.deepEqual(Buffer.from(actual.stderrBytes), oracle.stderr);
  });
}

const regularCases: readonly ReadCase[] = [
  { name: "ordinary failure retains scalar", args: "-u3 value", expected: { stderr: readError } },
  { name: "zero-timeout bypasses invalid name", args: "-t0 -u3 bad-name", expected: { status: 0 } },
  { name: "readiness precedes zero count", args: "-t0 -u3 -n0 value", expected: { status: 0 } },
  { name: "positive timeout retains read-error behavior", args: "-t.02 -u3 value", expected: { stderr: readError } },
  { name: "zero count assigns empty scalar", args: "-n0 -u3 value", expected: { value: "" } },
  { name: "zero exact count clears array", args: "-N0 -u3 -a values", expected: { count: 0, array: "" } },
];

for (const entry of regularCases) test(`descriptor order VFS regular/recorded ad-hoc profile: ${entry.name}`, async context => {
  const subject = setup();
  context.after(() => subject.shell.dispose());
  await subject.fs.writeFile("/regular", Buffer.from("seed\n"));
  assert.equal((await subject.fs.stat("/regular")).type, "file");
  const source = `{ ${body(entry)}; } 3>>/regular`;
  const actual = await subject.shell.exec(source, { stdin: Buffer.from(input), env: { LC_ALL: "C" } });
  const capture = expected(entry.expected);
  context.diagnostic(JSON.stringify({ source, qualification: "Recorded ad-hoc Bash 5.2.37 regular-file observations; no native regular file is opened by this test",
    nativeEvidenceSha256: "a5786da306c7b3d29e27ea0c3bb656a10f152bf803595624bef85bc5b3e4bf15",
    stdoutHex: Buffer.from(actual.stdoutBytes).toString("hex"), stderrHex: Buffer.from(actual.stderrBytes).toString("hex"),
  }));
  assert.equal(actual.exitCode, 0);
  assert.deepEqual(await subject.fs.readFile("/regular"), Buffer.from("seed\n"));
  assert.deepEqual(Buffer.from(actual.stdoutBytes), capture.stdout);
  assert.deepEqual(Buffer.from(actual.stderrBytes), capture.stderr);
});

for (const entry of [
  { args: "-u3 -u0 value", redirect: "3<&0", events: ["validate:3", "validate:0", "borrow:0"] },
  { args: "-u3 -u0 value", redirect: "3>/dev/null", events: ["validate:3", "validate:0", "borrow:0"] },
  { args: "-u9 -u0 value", redirect: "", events: ["validate:9"] },
  { args: "-u0 -u9 value", redirect: "", events: ["validate:0", "validate:9"] },
]) test(`descriptor order public hooks validate each option and borrow final only: ${entry.args} ${entry.redirect}`, async context => {
  const events: string[] = [];
  const definition = readExtension();
  const subject = setup([{ ...definition, create() {
    const instance = definition.create();
    return { ...instance, builtins: instance.builtins.map(builtin => ({ ...builtin, execute(invocation) {
      const input = invocation.input;
      return builtin.execute({ ...invocation, input: {
        validateOpen(descriptor) { events.push(`validate:${descriptor}`); input.validateOpen(descriptor); },
        borrow(descriptor) { events.push(`borrow:${descriptor}`); return input.borrow(descriptor); },
      } });
    } })) };
  } }]);
  context.after(() => subject.shell.dispose());
  await subject.shell.exec(`read ${entry.args} ${entry.redirect}`, { stdin: Buffer.from(input) });
  assert.deepEqual(events, entry.events);
});

test("descriptor topology native: FD3 is a shell-created pipe and FD1 preserves saved output", nativeOptions(), () => {
  const result = native("printf 'pipe\\n' >&3; printf 'saved\\n'", true);
  assert.equal(result.status, 0);
  assert.deepEqual(result.stderr, Buffer.alloc(0));
  assert.deepEqual(result.stdout.toString().trimEnd().split("\n").sort(), ["pipe", "saved"]);
});

test("descriptor topology VFS: output-only FD3 feeds cat while FD1 preserves saved output", async context => {
  let checked = 0;
  const subject = setup([readExtension(), { name: "descriptor-topology", create: () => ({ builtins: [{ name: "checkfd", execute(invocation) {
    for (const descriptor of [3, 4]) {
      invocation.input.validateOpen(descriptor);
      assert.throws(() => invocation.input.borrow(descriptor), reason => reason instanceof FsError && reason.code === "EBADF");
    }
    checked++;
    return 0;
  } }] }) }]);
  context.after(() => subject.shell.dispose());
  const result = await subject.shell.exec(pipe("checkfd; printf 'pipe\\n' >&3; printf 'saved\\n'"));
  assert.equal(result.exitCode, 0);
  assert.equal(result.stderr, "");
  assert.equal(checked, 1);
  assert.deepEqual(result.stdout.split("\n").filter(Boolean).sort(), ["pipe", "saved"]);
});

test("descriptor timing native: blocked write-pipe readiness is followed by timeout assignment", nativeOptions(), () => {
  const result = native('value=OLD; read -t0 -u3 value; printf "ready=%s:<%s>;" "$?" "$value"; read -t.02 -u3 value; printf "timed=%s:<%s>" "$?" "$value"', true);
  assert.equal(result.status, 0);
  assert.deepEqual(result.stdout, Buffer.from("ready=1:<OLD>;timed=142:<>"));
  assert.deepEqual(result.stderr, Buffer.alloc(0));
});

import assert from "node:assert/strict";
import test from "node:test";
import { basicCommands } from "../../../../src/commands/basic.js";
import { createMemoryFileSystem } from "../../../../src/fs/memory/index.js";
import { readExtension } from "../../../../src/shell/extensions/read/index.js";
import { Shell } from "../../../../src/shell/shell.js";
import { authenticateOracle, nativeOptions, runNative } from "../trap/oracle.js";

interface DiagnosticCase {
  readonly name: string;
  readonly args: string;
  readonly status?: number;
  readonly next?: string;
  readonly value?: string;
  readonly array?: string;
  readonly raw?: boolean;
}

const cases: DiagnosticCase[] = [
  { name: "scalar name refuses before input", args: "$'\\xff'" },
  { name: "second scalar name refuses after earlier assignment", args: "value $'\\xff'", value: "first", next: "second tail" },
  { name: "scalar name after option terminator", args: "-- $'\\xff'" },
  { name: "scalar name from byte-valued variable", args: '"$bad"' },
  { name: "array name refuses after consuming record", args: "-a $'\\xff'", next: "second tail" },
  { name: "attached array name", args: "-a$'\\xff'", next: "second tail" },
  { name: "later valid array replaces earlier invalid name", args: "-a$'\\xff' -a values", status: 0, array: "first,word,", next: "second tail", raw: false },
  { name: "later invalid array preserves existing array", args: "-a values -a$'\\xff'", next: "second tail" },
  { name: "readiness bypasses invalid scalar without assignment", args: "-t0 $'\\xff'", status: 0, raw: false },
  { name: "readiness bypasses invalid array without clearing", args: "-t0 -a$'\\xff'", status: 0, raw: false },
  { name: "invalid descriptor precedes invalid scalar", args: "-u9 $'\\xff'", raw: false },
  { name: "invalid first scalar precedes distinct invalid array", args: "-a$'\\xfe' $'\\xff'" },
  { name: "hex count diagnostic retains suffix byte", args: "-n $'0x\\xff' value" },
  { name: "raw invalid option and usage", args: "-$'\\xff' value", status: 2 },
  { name: "attached operand after clustered raw flag", args: "-rn$'\\xff' value" },
  { name: "signed invalid count preserves the full operand", args: "-n $'-\\xff' value" },
  { name: "first raw numeric error wins over distinct later byte", args: "-n$'\\xff' -n$'\\xfe' value" },
  { name: "zero timeout does not mask invalid descriptor operand", args: "-t0 -u$'\\xff' value" },
];

for (const [flag, valid] of [["u", "0"], ["t", "1"], ["n", "1"], ["N", "1"]] as const) {
  cases.push(
    { name: `separated -${flag} operand`, args: `-${flag} $'\\xff' value` },
    { name: `attached -${flag} operand`, args: `-${flag}$'\\xff' value` },
    { name: `invalid -${flag} is not repaired by later valid operand`, args: `-${flag}$'\\xff' -${flag}${valid} value` },
    { name: `later invalid -${flag} retains its original operand`, args: `-${flag}${valid} -${flag}$'\\xff' value` },
  );
}

for (const entry of cases) {
  test(`read byte diagnostics: ${entry.name}`, nativeOptions(), async context => {
    const env = { ...process.env };
    assert.equal(env.SAFE_BASH_TEST_BASH_SHA256, "f5b331844c67482075aea7883153127668cc67f83a60a7b4362cc8469a9dc77d");
    const source = `bad=$'\\xff'; value=OLD; values=(KEEP STAY); read ${entry.args}; status=$?; printf 'read:%s value:<%s> array:<' "$status" "$value"; printf '%s,' "\${values[@]}"; printf '>;'; read -r tail; printf 'next:%s:<%s>' "$?" "$tail"`;
    const expected = runNative(source, "first word\nsecond tail\n", env);
    try {
      const shell = new Shell({
        fs: createMemoryFileSystem(),
        extensions: [readExtension()],
        limits: { maxWallClockMs: 2000, maxInputBytes: 4096, maxOutputBytes: 65536, maxCommands: 64 },
      });
      context.after(() => shell.dispose());
      for (const command of basicCommands()) shell.register(command);
      const actual = await shell.exec(source, { stdin: Buffer.from("first word\nsecond tail\n"), env: { LC_ALL: "C" } });
      context.diagnostic(JSON.stringify({
        source,
        native: { status: expected.status, stdoutHex: expected.stdout.toString("hex"), stderrHex: expected.stderr.toString("hex") },
        actual: { status: actual.exitCode, stdoutHex: Buffer.from(actual.stdoutBytes).toString("hex"), stderrHex: Buffer.from(actual.stderrBytes).toString("hex") },
      }));
      assert.equal(expected.status, 0);
      assert.deepEqual(expected.stdout, Buffer.from(`read:${entry.status ?? 1} value:<${entry.value ?? "OLD"}> array:<${entry.array ?? "KEEP,STAY,"}>;next:0:<${entry.next ?? "first word"}>`));
      assert.equal(expected.stderr.includes(255), entry.raw ?? true);
      assert.equal(expected.stderr.includes(254), false);
      assert.equal(actual.exitCode, expected.status);
      assert.deepEqual(Buffer.from(actual.stdoutBytes), expected.stdout);
      assert.deepEqual(Buffer.from(actual.stderrBytes), expected.stderr);
    } finally {
      assert.equal(authenticateOracle(env), expected.executable);
    }
  });
}

import assert from "node:assert/strict";
import test from "node:test";
import { basicCommands } from "../../../../src/commands/basic.js";
import { createMemoryFileSystem } from "../../../../src/fs/memory/index.js";
import { readExtension } from "../../../../src/shell/extensions/read/index.js";
import { Shell } from "../../../../src/shell/shell.js";
import { ShellLimitError } from "../../../../src/shell/types.js";
import { authenticateOracle, nativeOptions, runNative } from "../trap/oracle.js";

const operands = [
  ["overlong UTF-8 scalar", "$'\\xc0\\xaf'"],
  ["literal replacement scalar", "$'\\xef\\xbf\\xbd'"],
  ["newline and invalid scalar bytes", "$'name\\n\\xff'"],
  ["later invalid scalar bytes", "value $'\\xfe\\xff'"],
  ["UTF-8 option reports its first byte", "-$'\\xc3\\xa9'"],
  ["cluster stops at first invalid option byte", "-r$'\\xff\\xfe'"],
  ["attached count retains both invalid bytes", "-rn$'\\xff\\xfe' value"],
  ["exact count preserves surrounding whitespace", "-rN$' \\xff \\t' value"],
  ["timeout retains invalid fractional byte", "-t$'1.\\xff' value"],
  ["timeout suffix after six fractional digits", "-t$'0.000000\\xff' value"],
  ["timeout suffix after rounding digit", "-t$'0.0000001\\xff' value"],
  ["array name retains newline and invalid bytes", "-ra$'name\\n\\xff'"],
] as const;

for (const [name, args] of operands) test(`diagnostic review native: ${name}`, nativeOptions(), async context => {
  assert.equal(process.env.SAFE_BASH_TEST_BASH_SHA256, "f5b331844c67482075aea7883153127668cc67f83a60a7b4362cc8469a9dc77d");
  const source = `value=OLD; values=(KEEP); read ${args}; status=$?; printf 'status:<%s> value:<%s> array:<' "$status" "$value"; printf '<%s>' "\${values[@]}"; printf '>'; read -r rest; printf ' rest:<%s>' "$rest"`;
  const expected = runNative(source, "first word\nremaining\n");
  const shell = new Shell({ fs: createMemoryFileSystem(), extensions: [readExtension()], limits: { maxWallClockMs: 1500 } });
  for (const command of basicCommands()) shell.register(command);
  context.after(() => shell.dispose());
  try {
    const actual = await shell.exec(source, { stdin: "first word\nremaining\n", env: { LC_ALL: "C" } });
    assert.equal(actual.exitCode, expected.status);
    assert.deepEqual(Buffer.from(actual.stdoutBytes), expected.stdout);
    assert.deepEqual(Buffer.from(actual.stderrBytes), expected.stderr);
  } finally { assert.equal(authenticateOracle(), expected.executable); }
});

for (const delta of [0, -1]) test(`diagnostic review: usage and prior stdout share one exact byte allowance, delta=${delta}`, async context => {
  const diagnostic = Buffer.concat([Buffer.from("shell: line 1: read: -"), Buffer.from([255]), Buffer.from(": invalid option\n")]);
  const usage = Buffer.from("read: usage: read [-ers] [-a array] [-d delim] [-i text] [-n nchars] [-N nchars] [-p prompt] [-t timeout] [-u fd] [name ...]\n");
  const writes: Uint8Array[] = [];
  const shell = new Shell({ fs: createMemoryFileSystem(), extensions: [readExtension()], limits: { maxOutputBytes: 3 + diagnostic.length + usage.length + delta } });
  for (const command of basicCommands()) shell.register(command);
  context.after(() => shell.dispose());
  const execution = shell.exec("printf pre; read -$'\\xff'", { stderr: { async write(bytes) { writes.push(bytes.slice()); } } });
  if (delta === 0) {
    const result = await execution;
    assert.equal(result.exitCode, 2);
    assert.equal(result.stdout, "pre");
    assert.deepEqual(Buffer.from(result.stderrBytes), Buffer.concat([diagnostic, usage]));
    assert.equal(writes.length, 2);
  } else {
    await assert.rejects(execution, error => error instanceof ShellLimitError && error.limit === "maxOutputBytes");
    assert.deepEqual(Buffer.concat(writes), diagnostic);
    assert.equal(writes.length, 1);
  }
});

for (const maximum of [640, 1024]) test(`diagnostic review: raw diagnostic participates in expansion admission, limit=${maximum}`, async context => {
  let entered = 0; let diagnostics = 0; let writes = 0;
  const definition = readExtension();
  const shell = new Shell({ fs: createMemoryFileSystem(), limits: { maxExpansionBytes: maximum }, extensions: [{ ...definition, create() {
    const instance = definition.create();
    return { ...instance, builtins: instance.builtins.map(builtin => ({ ...builtin, execute(command) {
      entered++;
      return builtin.execute({ ...command, async diagnostic(message) { diagnostics++; await command.diagnostic(message); } });
    } })) };
  } }] });
  context.after(() => shell.dispose());
  const execution = shell.exec("read -n $'\\xff'", { stderr: { async write() { writes++; } } });
  if (maximum === 640) {
    await assert.rejects(execution, error => error instanceof ShellLimitError && error.limit === "maxExpansionBytes");
    assert.equal(writes, 0);
  } else {
    assert.equal((await execution).exitCode, 1);
    assert.equal(writes, 1);
  }
  assert.equal(entered, 1);
  assert.equal(diagnostics, 1);
});

function deferred() {
  let resolve!: () => void;
  const promise = new Promise<void>(done => { resolve = done; });
  return { promise, resolve };
}

function intercept<Target extends object>(subject: Target, overrides: Partial<Target>): Target {
  return new Proxy(subject, { get(target, key) {
    if (Object.hasOwn(overrides, key)) return Reflect.get(overrides, key);
    const value: unknown = Reflect.get(target, key, target);
    return typeof value === "function" ? value.bind(target) : value;
  } });
}

for (const cancel of [false, true]) for (const reason of [false, 0, "", null]) test(`diagnostic review: ${cancel ? "root cancellation" : "leaf stderr failure"} drains actual owned input (${String(reason)})`, { timeout: 2500 }, async context => {
  const memory = createMemoryFileSystem();
  await memory.writeFile("/input", Buffer.from("unread\n"));
  const closing = deferred();
  const release = deferred();
  const controller = new AbortController();
  let reads = 0; let closes = 0;
  let observed: { failure: unknown } | undefined;
  const writes: Uint8Array[] = [];
  const fs = intercept(memory, { async open(path, options) {
    const descriptor = await memory.open(path, options);
    return intercept(descriptor, {
      async read(...args) { reads++; return descriptor.read(...args); },
      async close() { closes++; closing.resolve(); await release.promise; await descriptor.close(); },
    });
  } });
  const definition = readExtension();
  const shell = new Shell({ fs, limits: { maxWallClockMs: 1500 }, extensions: [{ ...definition, create() {
    const instance = definition.create();
    return { ...instance, builtins: instance.builtins.map(builtin => ({ ...builtin, async execute(command) {
      if (cancel) return builtin.execute(command);
      try { return await builtin.execute(command); }
      catch (failure) { observed = { failure }; return 0; }
    } })) };
  } }] });
  context.after(async () => { release.resolve(); controller.abort(reason); await shell.dispose(); });
  let settled = false;
  const outcome = shell.exec("read -u0 -n $'\\xff' </input", { signal: controller.signal, stderr: { async write(bytes) {
    writes.push(bytes.slice());
    if (cancel) controller.abort(reason);
    else throw reason;
  } } }).then(result => ({ result }), failure => ({ failure })).finally(() => { settled = true; });
  try {
    await closing.promise;
    await new Promise<void>(resolve => setImmediate(resolve));
    assert.equal(settled, false);
  } finally { release.resolve(); }
  const actual = await outcome;
  if (cancel) {
    assert.ok("failure" in actual);
    assert.equal(actual.failure, reason);
  } else {
    assert.ok("result" in actual);
    assert.equal(actual.result.exitCode, 0);
    assert.ok(observed);
    assert.equal(observed.failure, reason);
  }
  assert.equal(reads, 0);
  assert.equal(closes, 1);
  assert.equal(writes.length, 1);
  assert.deepEqual(Buffer.concat(writes), Buffer.concat([Buffer.from("shell: line 1: read: "), Buffer.from([255]), Buffer.from(": invalid number\n")]));
});

import assert from "node:assert/strict";
import test from "node:test";
import type { ShellExtensionContext, ShellInputBorrow } from "../../../../src/shell/extensions.js";
import type { ReadLine } from "../../../../src/shell/input.js";
import { readExtension } from "../../../../src/shell/extensions/read/index.js";
import { shellValueBytes, shellValueFromBytes, shellValueText, type ShellValue } from "../../../../src/contracts/value.js";

function deferred<Value>() {
  let resolve!: (value: Value) => void;
  let reject!: (reason: unknown) => void;
  const promise = new Promise<Value>((done, fail) => { resolve = done; reject = fail; });
  return { promise, resolve, reject };
}

function harness(input: Pick<ShellInputBorrow, "read" | "release">, args: readonly ShellValue[] = []) {
  const controller = new AbortController();
  const cleanups: (() => void | Promise<void>)[] = [];
  const assignments: string[] = [];
  const diagnostics: ShellValue[] = [];
  const context: ShellExtensionContext = {
    command: "read", args: args.map(shellValueText), argumentValues: args, status: 0, functionDepth: 0, sourceDepth: 0,
    stdin: { async *[Symbol.asyncIterator]() { yield new Uint8Array(); } },
    stdout: { write: async () => undefined }, stderr: { write: async () => undefined },
    scope: {}, signal: controller.signal,
    bindings: {
      describe: () => ({ kind: "unset", readonly: false, exported: false }),
      get: () => undefined,
      assign: async name => { assignments.push(name); },
      prepare: async () => { throw new Error("Unexpected array preparation"); },
      openIndexed: async () => { throw new Error("Unexpected incremental indexed admission"); },
    },
    input: { validateOpen() { throw new Error("Unexpected descriptor validation"); }, borrow() {
      assert.equal(cleanups.length, 1);
      return { ...input, record: async () => { throw new Error("Unexpected raw record read"); }, readiness: () => { throw new Error("Unexpected readiness query"); } };
    } },
    evaluate: async () => { throw new Error("Unexpected evaluate"); },
    variable: () => undefined,
    accountSource: () => undefined,
    diagnostic: async message => { diagnostics.push(message); },
    registerCleanup: cleanup => { cleanups.push(cleanup); },
  };
  const execute = () => Promise.resolve(readExtension().create().builtins[0]!.execute(context));
  return { context, controller, cleanups, assignments, diagnostics, execute };
}

function record(release: () => Promise<void>): ReadLine {
  return { value: "one", shellValue: "one", escaped: new Set(), escapedByteOffsets: [], terminated: true, reason: "delimiter", fields: async () => [{ start: 0, end: 3, value: "one" }], release };
}

for (const reason of [undefined, false, 0, "", { readStatus: 1 }]) {
  test(`primary read failure preserves ${String(reason)} through rejecting release`, async () => {
    let releases = 0;
    const testCase = harness({ read: async () => { throw reason; }, release: async () => { releases++; throw new Error("secondary close"); } });
    let observed: { reason: unknown } | undefined;
    try { await testCase.execute(); } catch (error) { observed = { reason: error }; }
    assert.ok(observed);
    assert.equal(observed.reason, reason);
    assert.equal(releases, 1);
    await assert.rejects(Promise.resolve(testCase.cleanups[0]!()), /secondary close/u);
    assert.equal(releases, 1);
    assert.deepEqual(testCase.assignments, []);
  });
}

test("close blocks assignment, drains late read acquisition, and releases record once", async () => {
  const pending = deferred<ReadLine>();
  const admitted = deferred<void>();
  let recordsReleased = 0;
  let inputsReleased = 0;
  const testCase = harness({
    read() { admitted.resolve(); return pending.promise; },
    release: async () => { inputsReleased++; },
  });
  const execution = testCase.execute();
  const rejection = assert.rejects(execution, /Read invocation is closed/u);
  await admitted.promise;
  let closed = false;
  const cleanup = Promise.resolve(testCase.cleanups[0]!()).then(() => { closed = true; });
  await Promise.resolve();
  assert.equal(closed, false);
  assert.equal(inputsReleased, 0);
  pending.resolve(record(async () => { recordsReleased++; }));
  await rejection;
  await cleanup;
  await testCase.cleanups[0]!();
  assert.equal(recordsReleased, 1);
  assert.equal(inputsReleased, 1);
  assert.deepEqual(testCase.assignments, []);
});

test("root falsey cancellation wins while cooperative resource release drains", async () => {
  const closing = deferred<void>();
  const pending = deferred<void>();
  const testCase = harness({
    read: async () => record(async () => undefined),
    release() { closing.resolve(); return pending.promise; },
  });
  const execution = testCase.execute();
  let settled = false;
  const observed = execution.then(() => ({ success: true }), reason => ({ reason })).finally(() => { settled = true; });
  await closing.promise;
  testCase.controller.abort(false);
  await Promise.resolve();
  assert.equal(settled, false);
  pending.reject(new Error("secondary close"));
  const outcome = await observed;
  assert.ok("reason" in outcome);
  assert.equal(outcome.reason, false);
});

test("failed diagnostic retains exact failure rather than returning a diagnosed status", async () => {
  const testCase = harness({ read: async () => { throw new Error("Must not read"); }, release: async () => undefined }, ["-Q"]);
  const context: ShellExtensionContext = { ...testCase.context, diagnostic: async () => { throw false; } };
  let observed: { reason: unknown } | undefined;
  try { await readExtension().create().builtins[0]!.execute(context); } catch (reason) { observed = { reason }; }
  assert.ok(observed);
  assert.equal(observed.reason, false);
});

test("synchronous cleanup registration closes admission without a TDZ or input acquisition", async () => {
  const testCase = harness({ read: async () => { throw new Error("Must not read"); }, release: async () => undefined });
  let completion: void | Promise<void> = undefined;
  let acquisitions = 0;
  const context: ShellExtensionContext = {
    ...testCase.context,
    registerCleanup(cleanup) { completion = cleanup(); },
    input: { validateOpen() { throw new Error("Must not validate"); }, borrow() { acquisitions++; throw new Error("Must not acquire"); } },
  };
  await assert.rejects(Promise.resolve(readExtension().create().builtins[0]!.execute(context)), /Read invocation is closed/u);
  await completion;
  assert.equal(acquisitions, 0);
});

test("raw diagnostic failure retains bytes and primary falsey reason while input cleanup drains", async () => {
  const closing = deferred<void>();
  const release = deferred<void>();
  let releases = 0;
  let diagnostic: ShellValue | undefined;
  const subject = harness({
    read: async () => { throw new Error("Must not consume invalid option input"); },
    release() { releases++; closing.resolve(); return release.promise; },
  }, ["-u0", "-t", shellValueFromBytes(Uint8Array.of(255))]);
  const context: ShellExtensionContext = { ...subject.context, diagnostic: async value => { diagnostic = value; throw false; } };
  let settled = false;
  const execution = Promise.resolve(readExtension().create().builtins[0]!.execute(context));
  const rejection = assert.rejects(execution, reason => reason === false).finally(() => { settled = true; });
  try {
    await closing.promise;
    assert.equal(settled, false);
    assert.ok(diagnostic !== undefined);
    assert.deepEqual(shellValueBytes(diagnostic), new Uint8Array([...Buffer.from("read: "), 255, ...Buffer.from(": invalid timeout specification")]));
    assert.deepEqual(subject.assignments, []);
  } finally {
    release.resolve();
    await rejection;
    await subject.cleanups[0]!();
  }
  assert.equal(releases, 1);
});

