test("Bash 5.2.37 partial timeout assigns partial array and preserves subsequent reads", nativeOptions(), async () => {
  const executable = authenticateOracle();
  const child = spawn(executable, ["--noprofile", "--norc", "-c", `read -t .04 -a values; printf '%s:' "$?"; printf '<%s>' "\${values[@]}"; printf '\\n'; read -r tail; printf 'tail=<%s>' "$tail"`, "shell"], {
    env: { PATH: "/__safe_bash_oracle_no_path__", LC_ALL: "C" }, stdio: ["pipe", "pipe", "pipe"], timeout: 2000, killSignal: "SIGKILL",
  });
  const stdout: Buffer[] = [];
  const stderr: Buffer[] = [];
  let bytes = 0;
  let released = false;
  child.stdout.on("data", (chunk: Buffer) => {
    bytes += chunk.length;
    if (bytes > 65536) { child.kill("SIGKILL"); return; }
    stdout.push(chunk);
    if (!released && chunk.includes(10)) { released = true; child.stdin.end("rest\n"); }
  });
  child.stderr.on("data", (chunk: Buffer) => { bytes += chunk.length; if (bytes > 65536) child.kill("SIGKILL"); else stderr.push(chunk); });
  child.stdin.on("error", () => undefined);
  const completion = new Promise<void>((resolve, reject) => {
    child.on("error", reject);
    child.on("close", (status, signal) => {
      try {
        assert.equal(signal, null);
        assert.equal(status, 0);
        assert.deepEqual(Buffer.concat(stdout), Buffer.from("142:<one><two>\ntail=<rest>"));
        assert.equal(Buffer.concat(stderr).length, 0);
        resolve();
      } catch (error) { reject(error); }
    });
  });
  child.stdin.write("one two");
  try { await completion; } finally { if (child.exitCode === null) child.kill("SIGKILL"); }
  assert.equal(authenticateOracle(), executable);
});

