async function nativePartial(script: string, bytes: Uint8Array) {
  const executable = authenticateOracle();
  const child = spawn(executable, ["--noprofile", "--norc", "-c", `IFS= read -rt1 -u3 start || exit 97; ${script}`, "shell"], {
    env: { LC_ALL: "C", PATH: "/__safe_bash_oracle_no_path__" },
    stdio: ["pipe", "pipe", "pipe", "pipe"], timeout: 2000, killSignal: "SIGKILL",
  });
  const stdout: Buffer[] = [], stderr: Buffer[] = [];
  let size = 0;
  let failure: { reason: unknown } | undefined;
  const fail = (reason: unknown): void => { failure ??= { reason }; child.kill("SIGKILL"); };
  const done = new Promise<{ status: number | null; signal: NodeJS.Signals | null }>(resolve => {
    child.once("error", fail);
    child.once("close", (status, signal) => resolve({ status, signal }));
  });
  const control = child.stdio[3];
  try {
    assert.ok(control instanceof Duplex && child.stdin && child.stdout && child.stderr);
    const capture = (target: Buffer[]) => (chunk: Buffer): void => {
      size += chunk.length;
      if (size > 65536) { fail(new Error("Native output exceeded bound")); return; }
      target.push(Buffer.from(chunk));
    };
    child.stdout.on("data", capture(stdout)); child.stderr.on("data", capture(stderr));
    child.stdout.on("error", fail); child.stderr.on("error", fail);
    child.stdin.on("error", fail); control.on("error", fail);
    child.stdin.write(bytes, error => { if (error) fail(error); else control.end("start\n"); });
    const outcome = await done;
    if (failure) throw failure.reason;
    assert.equal(outcome.signal, null, "Native timeout guard is not an accepted read timeout");
    assert.equal(authenticateOracle(), executable);
    return { ...outcome, stdout: Buffer.concat(stdout), stderr: Buffer.concat(stderr) };
  } finally {
    if (child.exitCode === null && child.signalCode === null) child.kill("SIGKILL");
    await done;
    child.stdin?.destroy(); control?.destroy();
  }
}

